USE poketrader;
-- Expansion-series names and requested set codes.
-- Note: 30CC is four characters, so setCode should be CHAR(4) or VARCHAR(4).
INSERT INTO sets (setName, setCode)
VALUES
    ('Mega Evolution', '30CC'),
    ('Mega Evolution', '30C'),
    ('Mega Evolution', 'PBL'),
    ('Mega Evolution', 'CRI'),
    ('Mega Evolution', 'POR'),
    ('Mega Evolution', 'ASC'),
    ('Mega Evolution', 'PFL'),
    ('Mega Evolution', 'MEG'),
    ('Platinum', 'ARC'),
    ('Platinum', 'SUV'),
    ('Platinum', 'RRL'),
    ('Platinum', 'PLT');

-- Pack records for the selected expansions.
-- TRUE is stored as 1 by MySQL when available is TINYINT(1).
-- Note: 30CC is four characters, so setCode should be CHAR(4) or VARCHAR(4).
INSERT INTO packs (packName, packID, available, setCode)
VALUES
    ('30th Classic Collection', 1, TRUE, '30CC'),
    ('30th Celebration', 2, TRUE, '30C'),
    ('Pitch Black', 3, TRUE, 'PBL'),
    ('Chaos Rising', 4, TRUE, 'CRI'),
    ('Perfect Order', 5, TRUE, 'POR'),
    ('Ascended Heroes', 6, TRUE, 'ASC'),
