    ('Arceus', 9, TRUE, 'ARC'),
    ('Supreme Victors', 10, TRUE, 'SUV'),
    ('Rising Rivals', 11, TRUE, 'RRL'),
    ('Platinum', 12, TRUE, 'PLT');

